def total_hamming_distance(nums):
    def count_bits(x):
        count = 0
        while x:
            x &= (x - 1)
            count += 1
        return count

    total = 0
    n = len(nums)
    for i in range(n):                                        # every pair of numbers is checked directly
        for j in range(i + 1, n):
            total += count_bits(nums[i] ^ nums[j])
    return total


if __name__ == "__main__":
    print(total_hamming_distance([4, 14, 2]))

