        int total = 0;
        int n = nums.length;
        for (int i = 0; i < n; i++) {                               // every pair of numbers is checked directly
            for (int j = i + 1; j < n; j++) {
                total += Integer.bitCount(nums[i] ^ nums[j]);
            }
        }
        return total;
    }

