def total_hamming_distance(nums):
    n = len(nums)
    total = 0
    for bit in range(32):
        set_count = 0
        for num in nums:
            if num & (1 << bit):
                set_count += 1                                       # how many numbers have this bit set
        total += set_count * (n - set_count)                           # every set/unset pair differs here
    return total


if __name__ == "__main__":
    print(total_hamming_distance([4, 14, 2]))

